import { QueueClient } from '@vercel/queue';
// @ts-expect-error generated by the build before Vercel bundles this entrypoint.
import { opsScheduler, parseOpsTick } from '../dist/services/opsScheduler.js';
// @ts-expect-error generated by the build.
import { opsControlRetry } from '../dist/services/automationSafety.js';

const queue = new QueueClient();
export default queue.handleNodeCallback(async (message: unknown) => {
  if (!parseOpsTick(message)) { console.error('Invalid ops scheduler tick rejected'); return; }
  const result = await opsScheduler.tick(message);
  console.log(JSON.stringify({ scheduler: true, ...result }));
}, {
  visibilityTimeoutSeconds: 300,
  retry: (error, meta) => opsControlRetry(error, meta.deliveryCount),
});
